#include "components/fps_light_ntt.hpp"
#include <random>
#include <iostream>
int main() {
 std::mt19937_64 rng(112319);
 for(int trial=0;trial<1400;++trial) {
  int n=rng()%220,m=rng()%220;
  if(trial<12) n=m=(1<<trial);
  std::vector<mint>a(n),b(m),expected(n&&m?n+m-1:0);
  for(auto&x:a)x=mint::word(rng()%(2*mint::mod()));
  for(auto&x:b)x=mint::word(rng()%(2*mint::mod()));
  for(int i=0;i<n;++i)for(int j=0;j<m;++j) {
   auto value=(std::uint64_t(a[i].val())*b[j].val()+expected[i+j].val())%mint::mod();
   expected[i+j]=mint::raw(value);
  }
  auto got=fps_light_detail::multiply(a,b);
  if(got!=expected)return 1;
  if(trial%17==0) {
   std::vector<mint> square(n?2*n-1:0);
   for(int i=0;i<n;++i)for(int j=0;j<n;++j)square[i+j]+=a[i]*a[j];
   if(fps_light_detail::multiply(a,a)!=square)return 2;
  }
 }
 fps_light_detail::Roots roots;
 for(int n=1;n<=65536;n*=2) {
  std::vector<mint>a(n);for(auto&x:a)x=mint::word(rng()%(2*mint::mod()));
  auto b=a;fps_light_detail::transform(a);fps_light_detail::transform(a,true);
  if(a!=b)return 3;
  roots.prepare(n);
  auto scalar=b,vector=b;
  for(int h=n/2;h;h/=2) fps_light_detail::stage<false>(scalar.data(),n,h,roots.forward.data()+h,false);
  fps_light_detail::transform(vector);
  if(scalar!=vector)return 4;
 }
 std::cout<<"PASS\n";
}

